457	    /**
458	     * Read the {@code Idempotency-Key} header from the current request, or {@code null} when the
459	     * header is absent, blank, or no request is bound to the thread. The header is not part of the
460	     * generated API signature, so it is read from the ambient request rather than a method parameter.
461	     */
462	    private static String currentIdempotencyKey() {
463	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
464	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
465	            return null;
466	        }
467	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
