475	    /**
476	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
477	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
478	     * compared case-insensitively with collapsed whitespace.
479	     */
480	    private static String collapse(String value) {
481	        if (value == null) {
482	            return "";
483	        }
484	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
485	    }
486	
487	    /**
488	     * Common street-type abbreviations expanded during address normalization.
489	     */
490	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
491	        "ST", "STREET",
492	        "RD", "ROAD",
493	        "AVE", "AVENUE");
494	
495	    /**
496	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
497	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
498	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
499	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
500	     * address maps to itself.
501	     */
502	    private static String normalizeAddress(String value) {
503	        if (value == null) {
504	            return "";
505	        }
506	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
507	        if (collapsed.isEmpty()) {
508	            return "";
509	        }
510	        String[] tokens = collapsed.split(" ");
511	        StringBuilder sb = new StringBuilder(collapsed.length());
512	        for (int i = 0; i < tokens.length; i++) {
513	            if (i > 0) {
514	                sb.append(' ');
515	            }
516	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
517	        }
518	        return sb.toString();
519	    }
