521	    /**
522	     * Derive the stable household identifier shared by owners with the same normalized last name
523	     * and postcode. It is a deterministic function of those two values, so every member of a
524	     * household independently derives the same identifier: the first 12 upper-case hex characters
525	     * of {@code SHA-256('V2' + '|' + normalizedLastName + '|' + postcode)}. The fixed {@code 'V2'}
526	     * version tag is mixed in so the value differs from the version-1 household id. A {@code null}
527	     * postcode contributes an empty segment.
528	     */
529	    private static String householdId(String normalizedLastName, String postcode) {
530	        try {
531	            byte[] digest = MessageDigest.getInstance("SHA-256")
532	                .digest((IdentityKeys.VERSION_TAG + "|" + normalizedLastName
533	                        + "|" + (postcode == null ? "" : postcode))
534	                    .getBytes(StandardCharsets.UTF_8));
535	            StringBuilder sb = new StringBuilder(digest.length * 2);
536	            for (byte b : digest) {
537	                sb.append(String.format("%02x", b));
538	            }
539	            return sb.substring(0, 12).toUpperCase();
540	        }
541	        catch (NoSuchAlgorithmException e) {
542	            throw new IllegalStateException("SHA-256 not available", e);
543	        }
544	    }
