546	    /**
547	     * Derive the identity key into which all duplicate detection is consolidated: the full lower-case
548	     * hex SHA-256 over {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. A
549	     * null email or last name contributes an empty segment. Two owners are duplicates only when their
550	     * whole identity keys are equal. Delegates to {@link IdentityKeys#identityKey} so the value here
551	     * matches the one the mapper exposes on the owner DTO.
552	     */
553	    private static String identityKey(String telephone, String email, String lastName) {
554	        return IdentityKeys.identityKey(telephone, email, lastName);
555	    }
