557	    /**
558	     * Count the existing owners that share the given first and last name, compared
559	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
560	     * namesakes that already existed at creation time (the new owner itself is not included).
561	     */
562	    private int countNamesakes(String firstName, String lastName) {
563	        return (int) this.clinicService.findAllOwners().stream()
564	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
565	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
566	                && existing.getLastName().equalsIgnoreCase(lastName))
567	            .count();
568	    }
