570	    /**
571	     * Count the existing owners that already belong to the given household (i.e. carry the same
572	     * non-null householdId). Called after any existing members have been backfilled with the shared
573	     * identifier but before the new owner is saved, so the returned value reflects the members that
574	     * already existed at creation time (the new owner itself is not included). Returns 0 when the
575	     * new owner is not part of any household ({@code householdId} is null).
576	     */
577	    private int countHouseholdMembers(String householdId) {
578	        if (householdId == null) {
579	            return 0;
580	        }
581	        return (int) this.clinicService.findAllOwners().stream()
582	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
583	            .count();
584	    }
