586	    /**
587	     * Compute the membership-level cap for a new owner joining the given household: one above the
588	     * current maximum membership level among the existing (non-deleted) members already carrying
589	     * this household id, using each member's effective (already-capped) level as returned to
590	     * clients. Returns {@code null} when the household has no existing member, so no cap applies.
591	     */
592	    private Integer householdMembershipLevelCap(String householdId) {
593	        if (householdId == null) {
594	            return null;
595	        }
596	        java.util.OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
597	            .filter(existing -> !existing.isDeleted())
598	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
599	            .mapToInt(existing -> ownerMapper.membershipLevel(existing))
600	            .max();
601	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
602	    }
