604	    /**
605	     * Find an existing owner that this new owner is a possible (soft) duplicate of: one whose
606	     * {@code soundex(lastName)} and postcode match the new owner's while its identity key differs (so
607	     * the two are not the same identity, which would already have been rejected as a 409). When
608	     * several existing owners match, the earliest (lowest id) is returned so the result is
609	     * deterministic. Returns {@code null} when there is no such owner — including when the new owner
610	     * has no last name or postcode, since a shared postcode is required to match.
611	     */
612	    private Owner findPossibleDuplicate(String lastName, String postcode, String identityKey) {
613	        if (isBlank(lastName) || isBlank(postcode)) {
614	            return null;
615	        }
616	        String soundex = IdentityKeys.soundex(lastName);
617	        return this.clinicService.findAllOwners().stream()
618	            .filter(existing -> !existing.isDeleted())
619	            .filter(existing -> soundex.equals(IdentityKeys.soundex(existing.getLastName())))
620	            .filter(existing -> postcode.equals(existing.getPostcode()))
621	            .filter(existing -> !identityKey.equals(
622	                identityKey(existing.getTelephone(), existing.getEmail(), existing.getLastName())))
623	            .min(java.util.Comparator.comparing(Owner::getId))
624	            .orElse(null);
625	    }
