676	    /** Fixed public holidays the business-day roll skips. */
677	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
678	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
679	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
