681	    /**
682	     * Roll a date forward onto a business day: Saturdays, Sundays and listed public holidays are
683	     * advanced one day at a time until a non-weekend, non-holiday day is reached, while an ordinary
684	     * business day is returned unchanged. Used so the effective registration date (whether supplied
685	     * or defaulted) always falls on a business day.
686	     */
687	    private static LocalDate toBusinessDay(LocalDate date) {
688	        while (isWeekendOrHoliday(date)) {
689	            date = date.plusDays(1);
690	        }
691	        return date;
692	    }
693	
694	    private static boolean isWeekendOrHoliday(LocalDate date) {
695	        return switch (date.getDayOfWeek()) {
696	            case SATURDAY, SUNDAY -> true;
697	            default -> PUBLIC_HOLIDAYS.contains(date);
698	        };
699	    }
