701	    /**
702	     * Build the unified member id for a new owner: {@code '<REGION><FY><HASH8><CHK>'} where REGION is
703	     * the region derived from the owner's postcode/city, FY is the 2-digit fiscal year of the
704	     * (business-day-adjusted) {@code registrationDate}, HASH8 is the first 8 upper-case hex characters
705	     * of {@code SHA-256(normalizedTelephone + lastName)}, and CHK is a single Luhn check digit (0-9)
706	     * computed over the digits contained in the {@code '<REGION><FY><HASH8>'} base
707	     * (e.g. {@code 'NSW261A2B3C4D9'}).
708	     */
709	    private static String memberId(String region, LocalDate registrationDate,
710	                                   String normalizedTelephone, String lastName) {
711	        String fy = String.format("%02d",
712	            OwnerMapper.fiscalYearStart(registrationDate) % 100);
713	        String hash8 = hash8(normalizedTelephone + (lastName == null ? "" : lastName));
714	        String base = region + fy + hash8;
715	        return base + luhnCheckDigit(base);
716	    }
717	
718	    /**
719	     * Compute a single Luhn check digit (0-9) over the digit characters contained in {@code value};
720	     * non-digit characters (e.g. the region's letters or the hex letters of HASH8) are skipped.
721	     */
722	    private static int luhnCheckDigit(String value) {
723	        int sum = 0;
724	        boolean dbl = true;
725	        for (int i = value.length() - 1; i >= 0; i--) {
726	            char c = value.charAt(i);
727	            if (c < '0' || c > '9') {
728	                continue;
729	            }
730	            int d = c - '0';
731	            if (dbl) {
732	                d *= 2;
733	                if (d > 9) {
734	                    d -= 9;
735	                }
736	            }
737	            sum += d;
738	            dbl = !dbl;
739	        }
740	        return (10 - (sum % 10)) % 10;
741	    }
742	
743	    /**
744	     * Ensure the computed member id is unique across existing owners. When {@code base} is already
745	     * free it is returned unchanged; otherwise {@code '-<n>'} is appended using the smallest {@code n}
746	     * of 2 or more that produces a value no existing owner already carries.
747	     */
748	    private String deduplicateMemberId(String base) {
749	        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
750	            .map(Owner::getMemberId)
751	            .filter(java.util.Objects::nonNull)
752	            .collect(java.util.stream.Collectors.toSet());
753	        if (!inUse.contains(base)) {
754	            return base;
755	        }
756	        int n = 2;
757	        while (inUse.contains(base + "-" + n)) {
758	            n++;
759	        }
760	        return base + "-" + n;
761	    }
