763	    /**
764	     * First 8 upper-case hex characters of {@code SHA-256(input)}.
765	     */
766	    private static String hash8(String input) {
767	        try {
768	            byte[] digest = MessageDigest.getInstance("SHA-256")
769	                .digest(input.getBytes(StandardCharsets.UTF_8));
770	            StringBuilder sb = new StringBuilder(digest.length * 2);
771	            for (byte b : digest) {
772	                sb.append(String.format("%02x", b));
773	            }
774	            return sb.substring(0, 8).toUpperCase();
775	        }
776	        catch (NoSuchAlgorithmException e) {
777	            throw new IllegalStateException("SHA-256 not available", e);
778	        }
779	    }
