781	    /**
782	     * Derive the owner's region, preferring the postcode: look up the region by postcode range first
783	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), then fall back to the city-to-region table
784	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is absent or in no known
785	     * range. Returns {@code 'UNKNOWN'} when neither source resolves a region. This mirrors the
786	     * mapper's locality derivation, so the customer code's region segment and the owner's locality
787	     * always agree.
788	     */
789	    private static String deriveRegion(String postcode, String city) {
790	        if (postcode != null && postcode.matches("\\d{4}")) {
791	            int value = Integer.parseInt(postcode);
792	            for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
793	                int[] range = entry.getValue();
794	                if (value >= range[0] && value <= range[1]) {
795	                    return entry.getKey();
796	                }
797	            }
798	        }
799	        if (city == null) {
800	            return "UNKNOWN";
801	        }
802	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
803	    }
804	
805	    /**
806	     * Derive the version-2 region code that goes INSIDE the identifiers (the member id): the plain
807	     * region from {@link #deriveRegion} with the fixed {@code 'V2'} version tag mixed in as a prefix
808	     * (e.g. {@code 'NSW'} -&gt; {@code 'V2NSW'}). This is used only for the identifiers; the
809	     * user-facing {@code locality}, {@code timezone} and the owner segment's derived region keep the
810	     * plain region code and never carry the version tag.
811	     */
812	    private static String deriveRegionV2(String postcode, String city) {
813	        return IdentityKeys.VERSION_TAG + deriveRegion(postcode, city);
814	    }
815	
816	    /**
817	     * The fixed city-to-region table used to validate a supplied postcode against the owner's city
818	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). A city not present here has no known region
819	     * and accepts any 4-digit postcode.
820	     */
821	    private static final Map<String, String> CITY_REGION = Map.of(
822	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
823	
824	    /**
825	     * The fixed region-to-postcode ranges (inclusive): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
826	     * Each entry is a two-element {@code {low, high}} array.
827	     */
828	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
829	        "NSW", new int[] {2000, 2099},
830	        "VIC", new int[] {3000, 3099},
831	        "QLD", new int[] {4000, 4099});
832	
833	    /**
834	     * Validate an optional owner postcode. Does nothing when no postcode was supplied (the field is
835	     * optional and the request contract stays backward-compatible). When supplied it must be exactly
836	     * 4 digits and, if the city maps to a known region, must fall within that region's inclusive
837	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
838	     * 4-digit postcode. A malformed or out-of-range postcode throws an
839	     * {@link InvalidOwnerFieldsException} so the request is rejected with a 400.
840	     */
841	    private static void validatePostcode(String city, String postcode) {
842	        if (postcode == null || postcode.isEmpty()) {
843	            return;
844	        }
845	        if (!postcode.matches("\\d{4}")) {
846	            throw new InvalidOwnerFieldsException(List.of("postcode"));
847	        }
848	        String region = city == null ? null : CITY_REGION.get(city);
849	        if (region == null) {
850	            return;
851	        }
852	        int[] range = REGION_POSTCODES.get(region);
853	        int value = Integer.parseInt(postcode);
854	        if (value < range[0] || value > range[1]) {
855	            throw new InvalidOwnerFieldsException(List.of("postcode"));
856	        }
857	    }
