859	    /**
860	     * Required national-number length for each E.164 country calling code we validate: a
861	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'} (NANP) number
862	     * carries 10. Country codes not listed here are accepted at any (generally valid) length.
863	     */
864	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
865	        "1", 10,
866	        "61", 9);
867	
868	    /**
869	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
870	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
871	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
872	     * The result must be a {@code '+'} followed by 8 to 15 digits, and for a recognised country code
873	     * its national-number length must match ({@code '+61'} requires 9 national digits, {@code '+1'}
874	     * requires 10); otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is
875	     * rejected with a 400.
876	     */
877	    private static String toE164(String raw) {
878	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
879	        boolean hasCountryCode = cleaned.startsWith("+");
880	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
881	        if (!digits.matches("\\d+")) {
882	            throw new InvalidOwnerFieldsException(List.of("telephone"));
883	        }
884	        if (!hasCountryCode) {
885	            if (digits.startsWith("0")) {
886	                digits = digits.substring(1);
887	            }
888	            digits = "61" + digits;
889	        }
890	        if (digits.length() < 8 || digits.length() > 15) {
891	            throw new InvalidOwnerFieldsException(List.of("telephone"));
892	        }
893	        // For a recognised country code, the national number (the digits after the code) must be
894	        // exactly the expected length for that country. Match the longest known code so a shorter
895	        // code that is a prefix of another cannot mask it.
896	        for (int codeLength = 3; codeLength >= 1; codeLength--) {
897	            if (digits.length() <= codeLength) {
898	                continue;
899	            }
900	            String countryCode = digits.substring(0, codeLength);
901	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
902	            if (requiredNationalLength != null) {
903	                if (digits.length() - codeLength != requiredNationalLength) {
904	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
905	                }
906	                break;
907	            }
908	        }
909	        return "+" + digits;
910	    }
