912	    /**
913	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
914	     * and a domain with at least one dot-separated label, none of which contain whitespace or
915	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
916	     */
917	    private static final Pattern EMAIL_PATTERN =
918	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
919	
920	    /**
921	     * Disposable email domains that are not accepted for an owner. An email whose domain (the part
922	     * after the {@code @}, compared case-insensitively) is on this blocklist is rejected with a 400.
923	     */
924	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
925	        "mailinator.com", "tempmail.com", "guerrillamail.com");
926	
927	    /**
928	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
929	     * supplied (the field is optional). When supplied it must be a syntactically valid address whose
930	     * domain is not on the disposable-domain blocklist, otherwise an
931	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400. A valid
932	     * address is returned lower-cased.
933	     */
934	    private static String normalizeEmail(String email) {
935	        if (email == null || email.isEmpty()) {
936	            return null;
937	        }
938	        String trimmed = email.trim();
939	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
940	            throw new InvalidOwnerFieldsException(List.of("email"));
941	        }
942	        String normalized = trimmed.toLowerCase();
943	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
944	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
945	            throw new InvalidOwnerFieldsException(List.of("email"));
946	        }
947	        return normalized;
948	    }
949	}
